graphql.query:
mutation RegisterRestaurant($registerDto: RegisterDto!) {
  registerRestaurant(registerDto: $registerDto) {
    message
    activation_token
    error { message }
  }
}

mutation ActivateRestaurant($activationDto: ActivationDto!) {
  activateRestaurant(activationDto: $activationDto) {
    restaurant {
      id
      name
      email
      city
      country
      address
      createdAt
    }
    error { message }
  }
}

mutation LoginRestaurant($loginDto: LoginDto!) {
  LoginRestaurant(loginDto: $loginDto) {
    restaurant {
      id
      name
      email
      city
      country
      address
      menus { id name }
      categories { id name }
      menuItems { id name price }
      operatingHours { id dayOfWeek openTime closeTime }
      createdAt
    }
    accessToken
    refreshToken
    error { message }
  }
}

query GetLoggedInRestaurant {
  getLoggedInRestaurant {
    restaurant {
      id
      name
      email
      city
      country
      address
      phone_number
      menus { id name }
      categories { id name description }
      menuItems { id name price available }
      operatingHours { id dayOfWeek openTime closeTime isClosed }
      createdAt
      updatedAt
    }
    accessToken
    refreshToken
    error { message }
  }
}

query LogOutRestaurant {
  logOutRestaurant {
    message
  }
}

query FindRestaurantsNear($findRestaurantsNearDto: FindRestaurantsNearDto!) {
  findRestaurantsNear(findRestaurantsNearDto: $findRestaurantsNearDto) {
    restaurants {
      id
      name
      city
      address
      menuItems { id name price }
    }
    error { message }
  }
}

